import React, { useEffect } from 'react';
import Lenis from 'lenis';
import { GraduationCap } from 'lucide-react';
import Navbar from './components/layout/Navbar.jsx';
import Footer from './components/layout/Footer.jsx';
import Home from './pages/Home.jsx';

function App() {
    useEffect(() => {
        const lenis = new Lenis();
        function raf(time) {
            lenis.raf(time);
            requestAnimationFrame(raf);
        }
        requestAnimationFrame(raf);

        return () => {
            lenis.destroy();
        };
    }, []);

    return (
        <>
            <Navbar />
            <main>
                <Home />
            </main>
            <Footer />

            {/* Floating Admissions Button */}
            <a 
                href="#admissions" 
                className="fixed bottom-6 right-6 lg:bottom-8 lg:right-8 bg-coral hover:bg-coral2 text-white font-display font-bold px-6 py-3.5 rounded-full shadow-[0_8px_30px_rgba(48,54,79,0.3)] transition-all duration-300 transform hover:-translate-y-1 hover:shadow-[0_12px_40px_rgba(48,54,79,0.4)] z-50 flex items-center gap-2 border border-gold/30"
            >
                <GraduationCap size={22} className="text-gold" />
                <span className="text-lg tracking-widest uppercase">Admissions</span>
            </a>
        </>
    );
}

export default App;
